={{
  (() => {
    const input = $('Google Sheets Trigger').item.json['PARA QUANDO SERÁ?']; // Ex: "13/08/2025 12:00:00"
    const [date, time] = input.split(" ");
    const [day, month, year] = date.split("/");
    return `${year}-${month}-${day} ${time}`;
  })()
}}

